update lm_car_application
driver_name = #{driverName}, car_number = #{carNumber}, driver_id = #{driverId}, phone = #{phone}, IDCard = #{idcard}, application_date = #{applicationDate}, out_date = #{outDate}, enter_date = #{enterDate}, isDeleted = #{isDeleted}, enter_status = #{enterStatus}, `status` = #{status}, carrier_id = #{carrierId}, carrier_name = #{carrierName}, before_weight = #{beforeWeight}, remark = #{remark}, reason = #{reason}, post_type = #{postType}, checker_id = #{checkerId}, checker_name = #{checkerName}, reason_key = #{reasonKey}, scrap = #{scrap}, scrap_key = #{scrapKey}, order_id = #{orderId}, businessType = #{businessType}, editFlag = #{editFlag}, supplyCode = #{supplyCode}, supplyName = #{supplyName}, enableControl = #{enableControl}, appointmentWeight = #{appointmentWeight}, toleranceAdd = #{toleranceAdd}, toleranceDec = #{toleranceDec}, upFloatingWeight = #{upFloatingWeight}, downFloatingWeight = #{downFloatingWeight}, businessDescription = #{businessDescription}, appointmentStatus = #{appointmentStatus}, custCode = #{custCode},
where application_id = #{applicationId}

update lm_car_application
cardID = #{cardId}, cardType = #{cardType}, car_number = #{carNumber}, truckNo2 = #{truckNo2}, isUpdate = #{isUpdate}, truckType = #{truckType}, createCardTime = #{createCardTime}, appointmentStatus = #{appointmentStatus},
where car_number = #{carNumber} and status = 2 and enter_status=1 and appointmentStatus=0 and serialNumber=#{serialNumber}

