lm_actualdeliverydate = #{lmActualdeliverydate}, lm_loadTime = #{lmLoadTime}, lm_dnlineref = #{lmDnlineref}, lm_batch = #{lmBatch}, lm_grossweight = #{lmGrossweight}, lm_weightunit = #{lmWeightunit}, lm_packagingid = #{lmPackagingid}, lm_car_number = #{lmCarNumber}, lm_update_time = #{lmUpdateTime},
where lm_dnnum = #{lmDnnum} And lm_dnline = #{lmDnline}

update lm_supplier_local
